const fs = require('fs');
const path = require('path');

const rhythmPath = path.join(process.cwd(), 'rhythm');

function listFiles(dir, allFiles = []) {
  const files = fs.readdirSync(dir);
  for (const file of files) {
    const name = path.join(dir, file);
    if (fs.statSync(name).isDirectory()) {
      listFiles(name, allFiles);
    } else {
      allFiles.push(name);
    }
  }
  return allFiles;
}

console.log('Files in rhythm/:');
try {
  const files = listFiles(rhythmPath);
  files.forEach(f => console.log(f));
} catch (e) {
  console.error(e);
}

console.log('\npackage.json:');
try {
  console.log(fs.readFileSync(path.join(rhythmPath, 'package.json'), 'utf8'));
} catch (e) {
  console.error(e);
}

console.log('\nvite.config.ts:');
try {
  console.log(fs.readFileSync(path.join(rhythmPath, 'vite.config.ts'), 'utf8'));
} catch (e) {
  console.error(e);
}

