@import "tailwindcss";

@theme {
  --font-sans: 'Geist Sans', system-ui, -apple-system, BlinkMacSystemFont, "Segoe UI", Roboto, "Helvetica Neue", Arial, sans-serif;
  --font-serif: 'Instrument Serif', serif;
  --font-mono: 'Geist Mono', monospace;
}

:root {
  --bg: #FBFBFA;
  --text: #111111;
  --text-muted: #787774;
  --border: #EAEAEA;
  --card-bg: #FFFFFF;
  --accent: #111111;
  --accent-bg: #F7F6F3;
}

.dark {
  --bg: #111111;
  --text: #FBFBFA;
  --text-muted: #787774;
  --border: #262626;
  --card-bg: #171717;
  --accent: #FBFBFA;
  --accent-bg: #262626;
}

body {
  background-color: var(--bg);
  color: var(--text);
  font-family: var(--font-sans);
  transition: background-color 0.3s ease, color 0.3s ease;
  -webkit-font-smoothing: antialiased;
}

.card {
  background-color: var(--card-bg);
  border: 1px solid var(--border);
  border-radius: 12px;
}

.btn-primary {
  background-color: var(--accent);
  color: var(--bg);
  padding: 0.75rem 1.5rem;
  border-radius: 6px;
  font-weight: 500;
}

